function validateProgress(p){if(!p||p.version!==1||typeof p.words!=='object'||!p.words||Array.isArray(p.words))throw Error('Geçersiz ilerleme dosyası');for(const [id,v] of Object.entries(p.words)){if(!/^[a-z0-9-]+$/.test(id)||!v||typeof v!=='object')throw Error('Geçersiz kelime kaydı');for(const key of ['streak','attempts','correct','due'])if(v[key]!==undefined&&(!Number.isFinite(v[key])||v[key]<0))throw Error('Geçersiz ilerleme değeri');if(v.star!==undefined&&typeof v.star!=='boolean')throw Error('Geçersiz favori değeri')}return p}
