let progress={version:1,words:{}},sets=[],current=null,mode='cards',index=0,flipped=false,deck=[],session=null,match=null,noticeTimer;
function notify(s){$('#status').textContent=s;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#status').textContent='',4500)}
try{const raw=localStorage.getItem(KEY);if(raw)progress=validateProgress(JSON.parse(raw));if(localStorage.getItem('ka-theme')==='dark')document.body.classList.add('dark')}catch{notify('Kayıt okunamadı. Yeni kayıtlar bu oturumda tutulacak.')}
