const state=w=>progress.words[w.id]||{};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function speak(text){if(!('speechSynthesis'in window)){notify('Bu tarayıcı sesli okumayı desteklemiyor.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=$('#accent')?.value||'en-GB';u.rate=$('#slow')?.checked?.valueOf()?0.7:0.9;const voice=speechSynthesis.getVoices().find(v=>v.lang===u.lang);if(voice)u.voice=voice;u.onerror=()=>notify('Ses oynatılamadı. Cihazındaki İngilizce ses ayarlarını kontrol et.');speechSynthesis.speak(u)}
