function renderStats(){const words=current?.words||[];$('#stats').innerHTML=[[(words.filter(w=>state(w).streak>=3)).length,'Öğrenilen'],[words.filter(w=>!state(w).due||state(w).due<=Date.now()).length,'Tekrar zamanı'],[words.filter(w=>state(w).star).length,'Favori']].map(([n,t])=>'<div class="stat"><strong>'+n+'</strong><span>'+t+'</span></div>').join('')}
