function selectSet(id){speechSynthesisSafe();current=sets.find(s=>s.id===id);$('#set-title').textContent=current.title;$('#set-count').textContent=current.words.length+' KELİME';$('#description').textContent=current.description;renderFolders();renderStats();renderStudyNotes();startMode(mode)}
function speechSynthesisSafe(){if('speechSynthesis'in window)speechSynthesis.cancel()}
function wordMeta(w){return [w.ipa,w.partOfSpeech,w.level==='unknown'?'':w.level].filter(Boolean).join(' · ')}
