function renderWords(){const words=filtered();$('#words').innerHTML=words.length?words.map(w=>'<article class="word-row"><div><strong>'+esc(w.term)+'</strong><small>'+esc(wordMeta(w))+'</small></div><div>'+esc(w.meaning)+'<br><small>'+esc(w.examples[0]?.en||'')+'</small>'+wordNotes(w)+'</div><div class="controls"><button data-speak="'+w.id+'" aria-label="'+esc(w.term)+' telaffuzunu dinle">▶</button><button data-star="'+w.id+'" aria-label="'+esc(w.term)+' favori" aria-pressed="'+!!state(w).star+'">'+(state(w).star?'★':'☆')+'</button></div></article>').join(''):'<p class="empty">Bu filtreye uygun kelime yok.</p>';$('#words').querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(current.words.find(w=>w.id===b.dataset.speak).term));$('#words').querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{const w=current.words.find(w=>w.id===b.dataset.star);progress.words[w.id]={...state(w),star:!state(w).star};save();renderWords();renderStats()})}
const modes=[['cards','01 Kartlar'],['learn','02 Öğren'],['write','03 Yaz'],['listen','04 Dinle'],['test','05 Test'],['match','06 Eşleştir'],['review','07 Tekrar']];
function startMode(next){speechSynthesisSafe();mode=next;index=0;flipped=false;session=null;match=null;deck=filtered();$('#modes').innerHTML=modes.map(([id,label])=>'<button data-mode="'+id+'" class="'+(id===mode?'active':'')+'" aria-pressed="'+(id===mode)+'">'+label+'</button>').join('');$('#modes').querySelectorAll('button').forEach(b=>b.onclick=()=>startMode(b.dataset.mode));renderWords();renderWorkspace()}
function renderWorkspace(){const area=$('#workspace');if(!deck.length){area.innerHTML='<p class="empty">Gösterilecek kelime yok. Aramayı veya favori filtresini değiştir.</p>';return}
if(mode==='cards'){renderCard();return}
if(mode==='match'){renderMatch();return}
if(mode==='review'){deck=deck.filter(w=>!state(w).due||state(w).due<=Date.now());if(!deck.length){area.innerHTML='<p class="empty">Tekrarların tamamlandı. Yeni tekrar zamanı geldiğinde burada göreceksin.</p>';return}}
session={items:shuffle(deck).slice(0,mode==='test'?10:deck.length),pos:0,correct:0,answered:false,wrong:[]};renderQuestion()}
