function renderMatch(){if(!match){const words=shuffle(deck).slice(0,6);match={tiles:shuffle(words.flatMap(w=>[{id:w.id,side:'term',text:w.term},{id:w.id,side:'meaning',text:w.meaning}])),selected:null,done:new Set(),start:performance.now(),penalty:0}}
$('#workspace').innerHTML='<div class="toolbar"><p class="eyebrow">KELİME VE ANLAMINI EŞLEŞTİR</p><button id="new-match">Yeni oyun</button></div><p class="hint">Yanlış eşleştirme: +1 saniye. Süre ilk seçimde başlar.</p><div id="match-status" role="status"></div><div class="match-grid">'+match.tiles.map((t,i)=>'<button data-tile="'+i+'" '+(match.done.has(t.id)?'disabled':'')+' class="'+(match.done.has(t.id)?'matched':'')+'">'+esc(t.text)+'</button>').join('')+'</div>';
$('#new-match').onclick=()=>{match=null;renderMatch()};let started=false;$('#workspace').querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(!started){match.start=performance.now();started=true}const i=Number(b.dataset.tile),t=match.tiles[i];if(match.done.has(t.id)||match.selected===i)return;if(match.selected===null){match.selected=i;b.classList.add('selected');return}const prev=match.tiles[match.selected];$('#workspace').querySelector('[data-tile="'+match.selected+'"]').classList.remove('selected');if(prev.id===t.id&&prev.side!==t.side){match.done.add(t.id);$('#workspace').querySelectorAll('[data-tile]').forEach(btn=>{if(match.tiles[Number(btn.dataset.tile)].id===t.id){btn.classList.add('matched');btn.disabled=true}});$('#match-status').textContent='Eşleşti ✓';if(match.done.size===match.tiles.length/2){$('#match-status').textContent='Tamamlandı! '+((performance.now()-match.start)/1000+match.penalty).toFixed(1)+' saniye';notify('Tüm çiftleri eşleştirdin.')}}else{match.penalty++;$('#match-status').textContent='Bu çift eşleşmiyor. +1 saniye'}match.selected=null})}
$('#theme').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('ka-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}};
$('#search').oninput=()=>{if(current)startMode(mode)};$('#only-stars').onchange=()=>{if(current)startMode(mode)};
