try{sets=window.KA_SETS;if(!Array.isArray(sets))throw Error('Kelime verisi bulunamadı');if(sets.length)selectSet(sets[0].id);else $('#workspace').innerHTML='<p class="empty">Henüz kelime seti yok.</p>'}catch(err){$('#workspace').innerHTML='<p class="empty">Veriler yüklenemedi. data/generated/sets.js dosyasının mevcut olduğunu kontrol et.</p>';notify(err.message)}

